// when the id is unknown (e.g. grace period already elapsed).
// A slot whose state already went back to the pool is refused.
func (s *Server) reconnectTabContext(id string, streamID uint64) (*stateSlotTabContext, bool) {
	slot, ok := s.lookupTabContext(id)
	if !ok {
		return nil, false
	}
	slot.mu.Lock()
	defer slot.mu.Unlock()
	if slot.dead {
		return nil, false
	}
	if slot.timer != nil {
		slot.timer.Stop()
		slot.timer = nil
	}
	slot.streamID = streamID
	return slot, true
}

// closeStreamTabContext marks id as detached from streamID and starts
// the grace timer. If the client reconnects with the same id
// before the timer fires, the slot is reused as-is.
//
// A tab can hold two streams at once while the server still
// tears the older one down. Only the attached stream may detach.
func (s *Server) closeStreamTabContext(id string, streamID uint64) {
	slot, ok := s.lookupTabContext(id)
	if !ok {
		return
	}
	slot.mu.Lock()
	if slot.streamID != streamID {
		slot.mu.Unlock()
		return
	}
	slot.streamID = 0
	if slot.timer != nil {
		slot.timer.Stop()
	}
	slot.timer = time.AfterFunc(s.stateConf.GracePeriod, func() {
		slot.mu.Lock()
		// A stream reattached while this timer was already running,
		// or another timer got here first.
		if slot.streamID != 0 || slot.dead {
			slot.mu.Unlock()
			return
		}
		slot.dead = true
		st := slot.state
		slot.state = nil
		slot.mu.Unlock()
		// A stream can allocate a fresh slot under this id while this
		// one is on its way out. Drop only the slot this timer owns.
		stateInstancesTabContext.CompareAndDelete(id, slot)
		stateLiveInstances.Add(-1)
		if st != nil {
			statePoolTabContext.Put(st)
		}
	})
	slot.mu.Unlock()
}

func setupHandlers(s *Server) {
	// Pages
	s.mux.HandleFunc(
		"GET /",
		s.handlePageIndexGET)
	s.mux.HandleFunc(
		"GET /_$/{$}",
		s.handlePageIndexGETStream)
	s.mux.HandleFunc(
		"GET /other/{$}",
		s.handlePageOtherGET)
	s.mux.HandleFunc(
		"GET /other/_$/{$}",
		s.handlePageOtherGETStream)
	s.mux.HandleFunc(
		"GET /plain/{$}",
		s.handlePagePlainGET)
	s.mux.HandleFunc(
		"POST /bump/{$}",
		s.handlePOSTBump)
	s.mux.HandleFunc(
		"POST /note/{$}",
		s.handlePageIndexPOSTNote)
}

func (s *Server) httpErrIntern(
	w http.ResponseWriter, _ *http.Request,
	_ *datastar.ServerSentEventGenerator, msg string, err error,
) {
	s.logErr(msg, err)
	switch {
	case errors.Is(err, httperr.BadRequest):
		http.Error(w, http.StatusText(http.StatusBadRequest), http.StatusBadRequest)
	case errors.Is(err, httperr.Forbidden):
		http.Error(w, http.StatusText(http.StatusForbidden), http.StatusForbidden)
	case errors.Is(err, httperr.NotFound):
		http.Error(w, http.StatusText(http.StatusNotFound), http.StatusNotFound)
	case errors.Is(err, httperr.Conflict):
		http.Error(w, http.StatusText(http.StatusConflict), http.StatusConflict)
	default:
		http.Error(w, http.StatusText(http.StatusInternalServerError), http.StatusInternalServerError)
	}
}

func (s *Server) handlePOSTBump(w http.ResponseWriter, r *http.Request) {
	instanceID := r.Header.Get(stateInstanceIDHeader)
	if !s.verifyStateInstanceID(instanceID) {
		w.Header().Set(stateRetryHeader, stateRetryReconnect)
		http.Error(w, http.StatusText(http.StatusConflict), http.StatusConflict)
		return
	}
	slot, ok := s.lookupTabContext(instanceID)
	if !ok {
		w.Header().Set(stateRetryHeader, stateRetryReconnect)
		http.Error(w, http.StatusText(http.StatusConflict), http.StatusConflict)
		return
	}
	stateID := s.stateRouteKey(instanceID)
	slot.mu.Lock()
	defer slot.mu.Unlock()
	if slot.dead {
		w.Header().Set(stateRetryHeader, stateRetryReconnect)
		http.Error(w, http.StatusText(http.StatusConflict), http.StatusConflict)
		return
	}

	dispatch := func(
		e1 app.EventChanged,
	) error {
		{
			j, err := json.Marshal(e1)
			if err != nil {
				return fmt.Errorf("marshaling EventChanged JSON: %w", err)
			}
			p0 := e1.SubjectStateID
			subj := "changed." + p0
			err = s.messageBroker.Publish(r.Context(), s.messageBrokerMetrics, subj, j)
			if err != nil {
				return fmt.Errorf("publishing subject %q: %w", subj, err)
			}
		}
		return nil
	}
	err := s.app.POSTBump(r, slot.state, stateID, dispatch)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling action App.Bump", err)
		return
	}
}

func (s *Server) handlePageIndexGET(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/" {
		http.NotFound(w, r)
		return
	}

	// Mint the per-instance identifier for this page load.
	// The client echoes this value on action requests and on the SSE
	// stream connect via the Datapages-Instance header.
	instanceID, err := s.signStateInstanceID()
	if err != nil {
		s.httpErrIntern(w, r, nil, "minting state instance", err)
		return
	}
	w.Header().Set(stateInstanceIDHeader, instanceID)
	// The page carries an identifier that stands for one tab's state.
	// A cache that hands it to a second visitor hands over the state.
	w.Header().Set("Cache-Control", "no-store")

	p := app.PageIndex{
		App: s.app,
		Base: app.Base{
			App: s.app,
		},
	}
	body, err := p.GET(r)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling PageIndex.GET", err)
		return
	}

	bodyAttrs := func(w http.ResponseWriter) {
		writeBodyAttrOnVisibilityChange(w)
	}

	bodySuffix := func(w http.ResponseWriter) {

		_, _ = io.WriteString(w, `data-init="@get('/_$/')"`)
	}

	if err := s.writeHTML(
		w, r, nil, body, bodyAttrs, bodySuffix,
	); err != nil {
		s.logErr("rendering PageIndex", err)
		return
	}
}

func (s *Server) handlePageIndexGETStream(w http.ResponseWriter, r *http.Request) {
	if !s.checkIsDSReq(w, r) {
		return
	}

	instanceID := r.Header.Get(stateInstanceIDHeader)
	if !s.verifyStateInstanceID(instanceID) {
		w.Header().Set(stateRetryHeader, stateRetryReconnect)
		http.Error(w, http.StatusText(http.StatusConflict), http.StatusConflict)
		return
	}
	if _, live := s.lookupTabContext(instanceID); !live && !s.stateHasCapacity() {
		w.Header().Set("Retry-After", "5")
		http.Error(w,
			http.StatusText(http.StatusServiceUnavailable),
			http.StatusServiceUnavailable)
		return
	}
	stateID := s.stateRouteKey(instanceID)
	var slot *stateSlotTabContext

	p := app.PageIndex{
		App: s.app,
		Base: app.Base{
			App: s.app,
		},
	}
	s.handleStreamRequest(w, r, evSubjPageIndex(stateID),
		func(
			streamID uint64,
			sse *datastar.ServerSentEventGenerator,
		) error {
			if existing, ok := s.reconnectTabContext(instanceID, streamID); ok {
				slot = existing
			} else {
				slot = s.allocateTabContext(instanceID, streamID)
			}
			// A stream that gets no slot never opens: the event loop and the
			// close hook run only once this hook has returned nil,
			// which is why neither of them checks again.
			if slot == nil {
				return errStateAtCapacity
			}
			slot.mu.Lock()
			defer slot.mu.Unlock()
			return p.StreamOpen(r, streamID, slot.state)
		},
		func(streamID uint64) {
			s.closeStreamTabContext(instanceID, streamID)
		},
		func(
			streamID uint64,
			sse *datastar.ServerSentEventGenerator, ch <-chan msgbroker.Message,
		) {
			for msg := range ch {
				switch {
				case strings.HasPrefix(msg.Subject, EvSubjPrefChanged):
					var e app.EventChanged
					if err := json.Unmarshal(msg.Data, &e); err != nil {
						s.logErr("unmarshaling EventChanged JSON", err)
						continue
					}
					slot.mu.Lock()
					if slot.dead {
						slot.mu.Unlock()
						continue
					}
					if err := p.OnChanged(e, sse, slot.state); err != nil {
						s.logErr("handling PageIndex.OnChanged", err)
					}
					slot.mu.Unlock()
				}
			}
		})
}

func (s *Server) handlePageIndexPOSTNote(
	w http.ResponseWriter, r *http.Request,
) {
	if !s.checkIsDSReq(w, r) {
		return
	}
	instanceID := r.Header.Get(stateInstanceIDHeader)
	if !s.verifyStateInstanceID(instanceID) {
		w.Header().Set(stateRetryHeader, stateRetryReconnect)
		http.Error(w, http.StatusText(http.StatusConflict), http.StatusConflict)
		return
	}
	slot, ok := s.lookupTabContext(instanceID)
	if !ok {
		w.Header().Set(stateRetryHeader, stateRetryReconnect)
		http.Error(w, http.StatusText(http.StatusConflict), http.StatusConflict)
		return
	}
	stateID := s.stateRouteKey(instanceID)
	r.Body = http.MaxBytesReader(w, r.Body, DefaultBodySizeLimit)
	var signals struct {
		Note string `json:"note"`
	}
	if err := datastar.ReadSignals(r, &signals); err != nil {
		s.httpErrBad(w, "reading signals", err)
		return
	}
	slot.mu.Lock()
	defer slot.mu.Unlock()
	if slot.dead {
		w.Header().Set(stateRetryHeader, stateRetryReconnect)
		http.Error(w, http.StatusText(http.StatusConflict), http.StatusConflict)
		return
	}

	dispatch := func(
		e1 app.EventChanged,
	) error {
		{
			j, err := json.Marshal(e1)
			if err != nil {
				return fmt.Errorf("marshaling EventChanged JSON: %w", err)
			}
			p0 := e1.SubjectStateID
			subj := "changed." + p0
			err = s.messageBroker.Publish(r.Context(), s.messageBrokerMetrics, subj, j)
			if err != nil {
				return fmt.Errorf("publishing subject %q: %w", subj, err)
			}
		}
		return nil
	}
	p := app.PageIndex{
		App: s.app,
		Base: app.Base{
			App: s.app,
		},
	}
	err := p.POSTNote(r, slot.state, stateID, signals, dispatch)
	if err != nil {
		s.httpErrIntern(w, r, nil, "handling action PageIndex.Note", err)
		return
	}
}

